    @classmethod
    def InitFromBuf(cls, buf, pos):
        tmpApl = APL()
        tmpApl.Init(buf, pos)
        return cls.InitFromObj(tmpApl)

    @classmethod
    def InitFromPackedBuf(cls, buf, pos=0):
        n = flatbuffers.encode.Get(flatbuffers.packer.uoffset, buf, pos)
        return cls.InitFromBuf(buf, pos+n)

    @classmethod
    def InitFromObj(cls, tmpApl):
        x = APLT()
        x._UnPack(tmpApl)
        return x

    # APLT
    def _UnPack(self, APL):
        if APL is None:
            return
        self.APL_ID = APL.APL_ID()
        self.NAME = APL.NAME()
        self.SCENARIO_ID = APL.SCENARIO_ID()
        self.RFL_ID = APL.RFL_ID()
        self.LINK_ID = APL.LINK_ID()
        self.WINDOW_START = APL.WINDOW_START()
        self.WINDOW_STOP = APL.WINDOW_STOP()
        self.TIME_SYSTEM = APL.TIME_SYSTEM()
        if not APL.EXCEEDANCE_PERCENTIsNone():
            if np is None:
                self.EXCEEDANCE_PERCENT = []
                for i in range(APL.EXCEEDANCE_PERCENTLength()):
                    self.EXCEEDANCE_PERCENT.append(APL.EXCEEDANCE_PERCENT(i))
